changeSet.sql:
INSERT INTO clinlims.system_role ( id, name, description, is_grouping_role, grouping_parent, display_key, active, editable ) SELECT nextval('clinlims.system_role_seq'), 'Sample Management', 'Access to the visible Sample Management submenu entry', false, parent_role.id, 'role.sample.management', true, false FROM clinlims.system_role parent_role WHERE parent_role.name = 'Lab Unit Roles' AND NOT EXISTS ( SELECT 1 FROM clinlims.system_role existing WHERE existing.name = 'Sample Management' );
